@@ -0,0 +1,97 @@
+import { createHash, randomBytes, randomUUID, timingSafeEqual } from 'node:crypto';
+
+const json = (value) => JSON.parse(JSON.stringify(value));
+const digest = (value) => createHash('sha256').update(value).digest();
+const validString = (value) => typeof value === 'string' && value.length > 0;
+const actor = (principal) => `web:${principal.userId}:${principal.sessionId}`;
+
+export class WebEventStream {
+  constructor(opts) {
+    if (!opts?.coordination || typeof opts.coordination.snapshot !== 'function' || typeof opts.coordination.events !== 'function' || typeof opts.coordination.recordWebAudit !== 'function') throw new TypeError('web stream requires coordination authority');
+    this.coordination = opts.coordination;
+    this.allowedOrigins = new Set(opts.allowedOrigins ?? []);
+    this.repoIds = new Set(opts.repoIds ?? []);
+    this.now = opts.now ?? Date.now;
+    this.ticketTtlMs = opts.ticketTtlMs ?? 15_000;
+    this.replayLimit = opts.replayLimit ?? 1_000;
+    this.maxBufferedBytes = opts.maxBufferedBytes ?? 256 * 1024;
+    this.pollMs = opts.pollMs ?? 100;
+    this.tickets = new Map();
+  }
+
+  _audit(kind, principal, origin, details = {}) {
+    return this.coordination.recordWebAudit({ kind, userId: principal?.userId ?? null, sessionId: principal?.sessionId ?? null, credentialId: principal?.credentialId ?? null, origin, ...json(details) }, { actor: principal ? actor(principal) : 'web:anonymous', key: `web.audit:${randomUUID()}` });
+  }
+
+  _authorized(principal, origin, repoId) {
+    const expiry = Date.parse(principal?.expiresAt);
+    return validString(principal?.userId) && validString(principal?.sessionId) && validString(principal?.credentialId)
+      && principal.revoked !== true && Number.isFinite(expiry) && expiry > this.now()
+      && this.allowedOrigins.has(origin) && this.repoIds.has(repoId)
+      && Array.isArray(principal.repoIds) && principal.repoIds.includes(repoId)
+      && Array.isArray(principal.capabilities) && principal.capabilities.includes('observe');
+  }
+
+  issue(principal, origin, repoId) {
+    if (!this._authorized(principal, origin, repoId)) return { status: principal ? 403 : 401, body: { ok: false, error: { code: principal ? 'forbidden' : 'unauthenticated' } } };
+    const ticket = randomBytes(32).toString('base64url');
+    const id = randomUUID();
+    this.tickets.set(id, { hash: digest(ticket), expiresAt: this.now() + this.ticketTtlMs, sessionId: principal.sessionId, credentialId: principal.credentialId, repoId, origin, used: false });
+    this._audit('stream_ticket_issued', principal, origin, { repoId, ticketId: id });
+    return { status: 201, body: { ok: true, ticket: `${id}.${ticket}`, expiresAt: new Date(this.now() + this.ticketTtlMs).toISOString() } };
+  }
+
+  consume(value, principal, origin) {
+    const split = typeof value === 'string' ? value.indexOf('.') : -1;
+    const id = split > 0 ? value.slice(0, split) : '';
+    const secret = split > 0 ? value.slice(split + 1) : '';
+    const found = this.tickets.get(id);
+    const presented = digest(secret);
+    const valid = found && !found.used && found.expiresAt > this.now() && presented.length === found.hash.length && timingSafeEqual(presented, found.hash)
+      && found.sessionId === principal?.sessionId && found.credentialId === principal?.credentialId && found.origin === origin
+      && this._authorized(principal, origin, found.repoId);
+    if (!valid) return null;
+    found.used = true;
+    return { id, repoId: found.repoId };
+  }
+
+  open({ ticket, principal, origin, cursor }, res) {
+    const grant = this.consume(ticket, principal, origin);
+    if (!grant) return { status: principal ? 403 : 401, body: { ok: false, error: { code: principal ? 'forbidden' : 'unauthenticated' } } };
+    const snapshot = this.coordination.snapshot();
+    const boundary = snapshot.lastSeq;
+    const requested = cursor == null || cursor === '' ? null : Number(cursor);
+    if (requested !== null && (!Number.isSafeInteger(requested) || requested < Math.max(0, boundary - this.replayLimit) || requested > boundary)) {
+      this._audit('stream_snapshot_required', principal, origin, { repoId: grant.repoId, requestedCursor: Number.isFinite(requested) ? requested : null, boundary });
+      return { status: 409, body: { ok: false, error: { code: 'snapshot_required' }, snapshotCursor: boundary } };
+    }
+    const streamId = randomUUID();
+    res.writeHead(200, { 'content-type': 'text/event-stream; charset=utf-8', 'cache-control': 'no-store', connection: 'keep-alive', 'x-accel-buffering': 'no', 'access-control-allow-origin': origin, 'access-control-allow-credentials': 'true', vary: 'Origin', 'x-content-type-options': 'nosniff' });
+    let next = requested === null ? boundary + 1 : requested + 1;
+    let closed = false;
+    let timer = null;
+    const frame = (type, cursorValue, eventId, payload, provenance = 'coordination-authority') => ({ schemaVersion: 1, streamId, cursor: cursorValue, eventId, provenance, trust: 'authoritative', resource: { repoId: grant.repoId }, type, payload });
+    const send = (type, item) => {
+      const data = frame(type, item.seq, `coordination:${item.seq}`, item);
+      const encoded = `id: ${item.seq}\nevent: ${type}\ndata: ${JSON.stringify(data)}\n\n`;
+      if ((res.writableLength ?? 0) + Buffer.byteLength(encoded) > this.maxBufferedBytes) {
+        const lag = frame('lag', Math.max(0, next - 1), `lag:${streamId}`, { code: 'backpressure', reconnect: true });
+        res.write(`event: lag\ndata: ${JSON.stringify(lag)}\n\n`);
+        this._audit('stream_backpressure_disconnect', principal, origin, { repoId: grant.repoId, cursor: next - 1 });
+        closed = true; if (timer) clearInterval(timer); res.end(); return false;
+      }
+      res.write(encoded); next = item.seq + 1; return true;
+    };
+    if (requested === null) {
+      const item = { seq: boundary, snapshot: json(snapshot) };
+      res.write(`id: ${boundary}\nevent: snapshot\ndata: ${JSON.stringify(frame('snapshot', boundary, `snapshot:${boundary}`, item))}\n\n`);
+    }
+    this._audit('stream_connected', principal, origin, { repoId: grant.repoId, streamId, cursor: requested ?? boundary });
+    const pump = () => { for (const event of this.coordination.events(next)) if (!send('coordination', event)) break; };
+    pump();
+    if (!closed) { timer = setInterval(pump, this.pollMs); timer.unref?.(); }
+    const disconnect = () => { if (closed) return; closed = true; clearInterval(timer); try { this._audit('stream_disconnected', principal, origin, { repoId: grant.repoId, streamId, cursor: next - 1 }); } catch { /* disconnect remains harmless */ } };
+    res.on?.('close', disconnect); res.on?.('error', disconnect);
+    return null;
+  }
+}
